head.script:
scwin.CHART_DATA_URL ="/ui/sample/SBChart/COLUMNS/data/COLUMNS.json";
scwin.CHART_CONFIG = {
    axis: {
        x: {
            zoom: {                 // ★ X축 확대/이동 — 대용량 시계열 탐색
                type: "drag"        // 드래그로 구간 확대 (휠 방식은 "wheel")
            }
        }
    }
};
scwin.onpageload = async function () {
    var res = await $c.sbm.executeDynamic({ id: "sbm_sbchart", action: scwin.CHART_DATA_URL, method: "get", mediatype: "application/json", mode: "asynchronous", isProcessMsg: false });
    var data = res.responseJSON;
    $c.ext.drawChartData("line", data, chartWrap, scwin.CHART_CONFIG);
};
